schema:
Product    { id, name, category: TERM | WHOLE_LIFE | ENDOWMENT | ULIP,
             entryAge: [min, max], maxMaturityAge, term: [min, max],
             cover: [min, max], riders[], savingsShare, surrenderScheduleId }
RateTable  { productId, dims: ["age","sex","smoker","term","coverBand","frequency"],
             cells: [ { key: {...}, ratePer1000 } ], version }
Profile    { id, age, incomeHistory[≤3], dependants[], loans[], goals[],
             existingCover[ { kind: OWN | EMPLOYER, deathSumAssured } ], assets[] }
Advisor    { id, name, languages[], specialities[], licenceRef, licenceValidTo }
Slot       { id, advisorId, startUtc, endUtc, capacity, booked }
